        List<TraceView.Segment> segments = new ArrayList<>();
        jdbc.query("SELECT i.seq, i.leg_id, l.origin, l.destination FROM bag_itinerary i"
                        + " JOIN leg l ON l.leg_id = i.leg_id WHERE i.bag_tag = ? ORDER BY i.seq",
                rs -> {
